#!/usr/bin/env bash
# ai-validate-epic-freshness.sh — deterministic FRESHNESS + CONFLICT gate for an epic architecture.
#
# Promotes the epic-create skill's honor-based "Freshness verification" and "Conflict Detection" RULEs
# into a fail-closed script (does NOT judge architecture quality). Complements ai-validate-epic.sh
# (structure) — this checks the epic's claims against REPO REALITY:
#   FR1  no unfilled freshness placeholder ([YYYY-MM-DD] / [manual /] / [None / list])   → FAIL
#   FR2  a Freshness Declaration with a real 'Last verified' date exists                 → FAIL (--lenient: WARN)
#   FR3  no STALE stage-status claim: the epic must not assert a stage is complete/done/
#        merged when the epic's state.json says otherwise (the dangerous stale-optimism)  → FAIL
#   CF1  dangling repo references: cited scripts/contracts/.ai/.claude paths that do not
#        exist on disk (a stale/hallucinated artifact reference)                          → WARN
#        (advisory: prose paths can be illustrative/future; --strict promotes CF1 to FAIL)
#
# Usage: ai-validate-epic-freshness.sh <epic-arch.md | epic-id> [--root <dir>] [--strict] [--lenient]
# Exit:  0 PASS · 1 FAIL · 2 malformed/usage.
set -uo pipefail
derr() { echo "  ERROR $*" >&2; exit 2; }
command -v python3 >/dev/null 2>&1 || derr "python3 is required"

arch=""; root=""; strict=0; lenient=0
while [ $# -gt 0 ]; do case "$1" in
  --root)    root="$2"; shift 2 ;;
  --strict)  strict=1; shift ;;
  --lenient) lenient=1; shift ;;
  -h|--help) echo "usage: ai-validate-epic-freshness.sh <epic-arch|epic-id> [--root <dir>] [--strict] [--lenient]"; exit 0 ;;
  -*) derr "unknown flag: $1" ;;
  *)  if [ -z "$arch" ]; then arch="$1"; else derr "unexpected arg: $1"; fi; shift ;;
esac; done
[ -n "$arch" ] || derr "usage: ai-validate-epic-freshness.sh <epic-arch|epic-id> [--root <dir>]"
REPO_ROOT="${root:-$(git rev-parse --show-toplevel 2>/dev/null || pwd)}"

if [ -f "$arch" ]; then ARCH="$arch"; EPIC_DIR="$(cd "$(dirname "$arch")" && pwd)"
elif [ -f "$REPO_ROOT/.ai/epics/$arch/architecture.md" ]; then ARCH="$REPO_ROOT/.ai/epics/$arch/architecture.md"; EPIC_DIR="$REPO_ROOT/.ai/epics/$arch"
else derr "epic architecture not found: '$arch'"; fi
STATE="$EPIC_DIR/state.json"

EF_ARCH="$ARCH" EF_STATE="$STATE" EF_ROOT="$REPO_ROOT" EF_STRICT="$strict" EF_LENIENT="$lenient" python3 <<'PY'
import os, re, sys, json
ARCH=os.environ["EF_ARCH"]; STATE=os.environ["EF_STATE"]; ROOT=os.environ["EF_ROOT"]
STRICT=os.environ["EF_STRICT"]=="1"; LENIENT=os.environ["EF_LENIENT"]=="1"
fails=[]; warns=[]
def FAIL(m): fails.append(m)
def WARN(m): warns.append(m)
def OK(m):   sys.stdout.write("  OK    %s\n" % m)

text = open(ARCH, encoding="utf-8", errors="replace").read()
print("epic-freshness gate: %s" % os.path.basename(os.path.dirname(ARCH)))

def section(title):
    # return the body of a '## <title>' section up to the next '## '
    m = re.search(r"^##\s+%s\b" % re.escape(title), text, re.M)
    if not m: return None
    start = m.end()
    n = re.search(r"^##\s+", text[start:], re.M)
    return text[start:start+n.start()] if n else text[start:]

# ── FR1 / FR2  Freshness Declaration ──────────────────────────────────────────
fresh = section("Freshness Declaration")
PLACEHOLDERS = [r"\[YYYY-MM-DD\]", r"\[manual\s*/", r"\[None\s*/\s*list", r"\[List\b", r"Last verified against repo:\*\*\s*\[",]
if fresh is not None:
    hit = next((p for p in PLACEHOLDERS if re.search(p, fresh)), None)
    if hit: FAIL("FR1 freshness placeholder still present (%s) — the freshness-verification step was skipped" % hit)
    else:   OK("FR1 no unfilled freshness placeholder")
    date_m = re.search(r"Last verified against repo:\*\*\s*([0-9]{4}-[0-9]{2}-[0-9]{2})", fresh)
    if date_m: OK("FR2 Freshness Declaration carries a real 'Last verified' date (%s)" % date_m.group(1))
    else:
        (WARN if LENIENT else FAIL)("FR2 Freshness Declaration has no real 'Last verified: YYYY-MM-DD' date")
else:
    (WARN if LENIENT else FAIL)("FR2 no '## Freshness Declaration' section — it is mandatory (template) so the epic's currency is unproven")

# ── FR3  stale stage-status claim vs the epic's own state.json ────────────────
life = {}
if os.path.exists(STATE):
    try:
        st = json.load(open(STATE, encoding="utf-8")).get("stages") or {}
        for sid, v in st.items():
            life[sid] = (v.get("lifecycle") if isinstance(v, dict) else v) or ""
    except Exception as e:
        WARN("FR3 state.json present but unreadable (%s) — stage-claim cross-check skipped" % e)
if life:
    DONE = {"done", "merged", "complete", "completed"}
    # A TIGHT status ASSERTION (not a heading, not a compound like "DONE-proven"):
    #   'Stage <id>' immediately followed by an assertion connector (is/was/:/=/(),
    #   then optionally now/already, then a completion word NOT part of a hyphenated
    #   or longer word (negative lookahead (?![-\w])). Definition HEADINGS ('#… Stage
    #   X — <title>') are skipped, so a title containing 'done'/'complete' never fires.
    claim_re = re.compile(
        r"\bStage\s+(\d+(?:\.\d+)+[A-Za-z]?)\s*(?:is|was|:|=|\()\s*(?:now\s+|already\s+)?"
        r"(complete|completed|done|merged)(?![-\w])", re.I)
    seen=set(); checked=0
    for ln in text.splitlines():
        if re.match(r"^\s*#", ln): continue          # skip stage-definition headings
        for m in claim_re.finditer(ln):
            sid=m.group(1)
            if sid in seen: continue
            seen.add(sid)
            if sid in life:
                checked+=1
                if life[sid].lower() not in DONE:
                    FAIL("FR3 epic asserts Stage %s is '%s' but state.json lifecycle is '%s' (stale over-optimistic claim)"
                         % (sid, m.group(2).lower(), life[sid]))
    OK("FR3 stage completion assertions are consistent with state.json (%d checked)" % checked)
else:
    OK("FR3 no epic state.json stages to cross-check (pre-seed or none) — skipped")

# ── CF1  dangling repo references (WARN; --strict → FAIL) ─────────────────────
ref_re = re.compile(r"(?:scripts|contracts|\.ai|\.claude)/[A-Za-z0-9_./-]+\.(?:sh|md|ya?ml|json|py)")
refs = sorted(set(m.group(0) for m in ref_re.finditer(text)))
dangling = [r for r in refs if not os.path.exists(os.path.join(ROOT, r))]
if dangling:
    msg = "CF1 %d cited repo path(s) do not exist on disk: %s" % (len(dangling), ", ".join(dangling[:6]) + (" …" if len(dangling)>6 else ""))
    (FAIL if STRICT else WARN)(msg)
else:
    OK("CF1 all %d cited repo paths resolve on disk" % len(refs))

# ── verdict ───────────────────────────────────────────────────────────────────
for w in warns: sys.stderr.write("  WARN  %s\n" % w)
for f in fails: sys.stderr.write("  FAIL  %s\n" % f)
if fails:
    sys.stderr.write("  epic-freshness: %d failure(s)\n" % len(fails)); sys.exit(1)
print("  PASS  epic freshness/conflict validated%s" % (" (%d warning(s))" % len(warns) if warns else ""))
sys.exit(0)
PY
